<section class="page-title"><div><p class="eyebrow">MA FORMATION</p><h1><?= htmlspecialchars($course['title']) ?></h1><p>Validez les leçons et les QCM section par section.</p></div><strong><?= (int)($enrollment['progress']??0) ?>%</strong></section><div class="academy-sections"><?php foreach($modules as $i=>$module): ?><section class="panel academy-section"><header><span><?= $i+1 ?></span><div><h2><?= htmlspecialchars($module['title']) ?></h2><p><?= count($module['lessons']) ?> leçons</p></div></header><?php foreach($module['lessons'] as $lesson): ?><article><span><?= $lesson['type']==='video'?'▶':($lesson['type']==='text'?'¶':'↓') ?></span><div><strong><?= htmlspecialchars($lesson['title']) ?></strong><small><?= htmlspecialchars($lesson['type']) ?> · <?= (int)$lesson['duration'] ?> min</small></div><a class="btn secondary" href="/academie/lecon?id=<?= $lesson['id'] ?>">Ouvrir</a></article><?php endforeach ?><?php if($module['assessment']): ?><article class="composition"><span>?</span><div><strong><?= htmlspecialchars($module['assessment']['title']) ?></strong><small>QCM obligatoire · seuil <?= $module['assessment']['passing_score'] ?>%</small></div><a class="btn primary" href="/academie/composition?id=<?= $module['assessment']['id'] ?>">Composer</a></article><?php endif ?></section><?php endforeach ?><?php if(!$modules): ?><div class="panel admin-empty">Le programme de cette formation est en préparation.</div><?php endif ?><?php if($final): ?><section class="panel final-exam"><div><p class="eyebrow">EXAMEN FINAL · QCM</p><h2><?= htmlspecialchars($final['title']) ?></h2><p>Sa réussite déclenche automatiquement votre diplôme IFMAP.</p></div><a class="btn primary" href="/academie/composition?id=<?= $final['id'] ?>">Commencer l’examen</a></section><?php endif ?></div><style>.academy-sections{display:flex;flex-direction:column;gap:15px}.academy-section header,.academy-section article{display:flex;align-items:center;gap:14px;padding:17px 20px;border-bottom:1px solid var(--line)}.academy-section header>span{width:32px;height:32px;border-radius:50%;display:grid;place-items:center;background:var(--primary);color:#fff}.academy-section h2{font-size:15px;margin:0}.academy-section p,.academy-section small{color:var(--muted);margin:0}.academy-section article div{display:flex;flex:1;flex-direction:column}.composition{background:#faf9ff}.final-exam{padding:25px;display:flex;align-items:center;justify-content:space-between}</style>
